import{c as a,Q as e,j as n,m as s}from"./chunks/framework.BXc4yaFE.js";const g=JSON.parse('{"title":"别把 Fable 5 用成一次性外挂：先清理你的 AI 工作负债","description":"","frontmatter":{"url":"https://x.com/vincentlogic/status/2072728090183426474","title":"别把 Fable 5 用成一次性外挂：先清理你的 AI 工作负债","author":"VincentLogic","archived":"2026-07-03T00:00:00.000Z","handle":"@VincentLogic","published":"2026-07-02T00:00:00.000Z","stats":"66 likes · 7 retweets · 132 bookmarks · 14347 views","tags":["fable5","AI工作负债","context-debt","three-layer-structure","audit-prompt","review-agent","zh-cn"],"type":"twitter-article"},"headers":[],"relativePath":"research/tweets/2026-07-02-@VincentLogic-426474.md","filePath":"research/tweets/2026-07-02-@VincentLogic-426474.md","lastUpdated":1785909234000}'),l={name:"research/tweets/2026-07-02-@VincentLogic-426474.md"};function i(r,t,o,d,p,c){return e(),n("div",null,[...t[0]||(t[0]=[s(`<h1 id="别把-fable-5-用成一次性外挂-先清理你的-ai-工作负债-—-vincentlogic" tabindex="-1">别把 Fable 5 用成一次性外挂：先清理你的 AI 工作负债 — @VincentLogic <a class="header-anchor" href="#别把-fable-5-用成一次性外挂-先清理你的-ai-工作负债-—-vincentlogic" aria-label="Permalink to &quot;别把 Fable 5 用成一次性外挂：先清理你的 AI 工作负债 — @VincentLogic&quot;">​</a></h1><p><strong>來源</strong>：<a href="https://x.com/vincentlogic/status/2072728090183426474" target="_blank" rel="noreferrer">https://x.com/vincentlogic/status/2072728090183426474</a><strong>作者</strong>：VincentLogic（@VincentLogic） <strong>發布日期</strong>：2026-07-02 <strong>收錄日期</strong>：2026-07-03 <strong>類型</strong>：Twitter Article（簡體中文） <strong>統計</strong>：66 likes · 7 retweets · 132 bookmarks · 14347 views</p><hr><h2 id="全文摘要" tabindex="-1">全文摘要 <a class="header-anchor" href="#全文摘要" aria-label="Permalink to &quot;全文摘要&quot;">​</a></h2><p><strong>定位</strong>：反直覺建議：使用 Fable 5 的最高槓桿用法不是生成更多成品，而是清理過去幾個月積累的「AI 工作負債」，建立持久系統。</p><h3 id="ai-工作負債-ai-work-debt" tabindex="-1">AI 工作負債（AI Work Debt） <a class="header-anchor" href="#ai-工作負債-ai-work-debt" aria-label="Permalink to &quot;AI 工作負債（AI Work Debt）&quot;">​</a></h3><p>混亂的 Memory、重複的長期指令、互相衝突的 Rules、邊界不清的 Skills，以及沒有審核機制的工作流。</p><p><strong>根本原因</strong>：</p><ul><li>每次模型犯錯 → 臨時增加一條規則</li><li>需求改變 → 補充新指令</li><li>這些補丁從不清理 → 時間一長，重複規則、過期信息、衝突指令全堆在一起</li><li>「模型沒有變，工作環境變亂了。」</li></ul><h3 id="ai-工作系統三層結構" tabindex="-1">AI 工作系統三層結構 <a class="header-anchor" href="#ai-工作系統三層結構" aria-label="Permalink to &quot;AI 工作系統三層結構&quot;">​</a></h3><table tabindex="0"><thead><tr><th>層次</th><th>內容</th><th>特性</th></tr></thead><tbody><tr><td><strong>第一層：長期上下文</strong></td><td>CLAUDE.md、Auto Memory、按條件加載的 Rules</td><td>決定 session 開始時 Claude 能看到什麼</td></tr><tr><td><strong>第二層：Skills</strong></td><td>特定任務的知識/清單/步驟/工具</td><td>主動沉澱；觸發前只載入名稱+描述；問題在描述不清/邊界混亂</td></tr><tr><td><strong>第三層：審核機制</strong></td><td>事實/邏輯/格式/風險/完成標準的檢查</td><td>需要預先定義，不依賴生成 agent 自我評估</td></tr></tbody></table><p><strong>判斷規則</strong>：如果你反複把同一套清單/指令粘進對話，或 CLAUDE.md 某段變成「操作流程」→ 拆成按需調用的 Skill。</p><h3 id="fable-5-視窗三件事" tabindex="-1">Fable 5 視窗三件事 <a class="header-anchor" href="#fable-5-視窗三件事" aria-label="Permalink to &quot;Fable 5 視窗三件事&quot;">​</a></h3><p><strong>一、清理上下文負債</strong></p><p>讓 Fable 5 審計的七類問題：</p><ul><li>重複或語義相近的規則</li><li>互相矛盾的新舊指令</li><li>已過期的信息</li><li>被誤寫成全局規則的項目要求</li><li>應該遷移到 Skill 的多步驟流程</li><li>描述含糊/邊界不清/容易誤觸發的 Skills</li><li>沒有明確完成標準的要求</li></ul><p><strong>⚠️ 重要</strong>：不要讓模型未經確認就直接覆蓋文件。先輸出問題清單 + 推薦結構 + 修改 Diff，人工審核後再更新。</p><p><strong>二、沉澱可複用資產</strong></p><p>從聊天記錄中提取（不是原封不動塞進 Memory）：</p><ul><li>知識庫、Skills、內容模板、操作手冊、決策記錄、常見錯誤清單</li><li>「如果來不及完成任務，至少留下流程、模板、檢查清單和完成標準」</li></ul><p><strong>三、建立獨立審核系統</strong></p><p><strong>獨立 Agent 分工（避免自我讚美）</strong>：</p><ul><li>生成 Agent：只負責寫</li><li>審核 Agent：只負責挑錯</li><li>編輯 Agent：只負責調整節奏</li><li>事實檢查 Agent：只負責核對來源</li><li>人工：決定能否發布</li></ul><blockquote><p>「不要讓同一個 Agent 寫完文章後，再問它：你覺得這篇有沒有問題？它很容易沿著自己的思路，再次證明自己沒錯。」</p></blockquote><h3 id="直接可用審計-prompt" tabindex="-1">直接可用審計 Prompt <a class="header-anchor" href="#直接可用審計-prompt" aria-label="Permalink to &quot;直接可用審計 Prompt&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请对我现有的 Claude Code/Cowork 智能体系统进行完整审计。</span></span>
<span class="line"><span>检查范围包括：CLAUDE.md、Rules、Skills、Auto Memory、</span></span>
<span class="line"><span>Subagent 配置、审核标准和工作流文档。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>请识别：</span></span>
<span class="line"><span>- 重复或语义相近的规则</span></span>
<span class="line"><span>- 互相矛盾的指令</span></span>
<span class="line"><span>- 已经过期或缺少适用范围的信息</span></span>
<span class="line"><span>- 应该迁移到 Skill 的多步骤流程</span></span>
<span class="line"><span>- 描述模糊、边界不清或容易误触发的 Skills</span></span>
<span class="line"><span>- 缺少验证方式的关键要求</span></span>
<span class="line"><span>- 可以改造成测试、Hook、清单或 Reviewer Agent 的内容</span></span>
<span class="line"><span></span></span>
<span class="line"><span>先不要修改文件。请输出当前结构、问题清单、风险等级、</span></span>
<span class="line"><span>推荐结构和迁移方案。每项修改都要说明理由，并以 Diff 形式</span></span>
<span class="line"><span>供我审核。对于无法确定的信息，请明确标记，不要自行删除。</span></span></code></pre></div><hr><h2 id="研究摘要" tabindex="-1">研究摘要 <a class="header-anchor" href="#研究摘要" aria-label="Permalink to &quot;研究摘要&quot;">​</a></h2><p><strong>TL;DR</strong>：使用 Fable 5 的最高槓桿用法是清理「AI 工作負債」（混亂 Memory/衝突 Rules/邊界不清 Skills）；三層結構（長期上下文/Skills/審核機制）；獨立審核 agent 分工；提供直接可用審計 prompt（輸出問題清單+Diff，不直接覆蓋文件）。</p><h3 id="核心論點" tabindex="-1">核心論點 <a class="header-anchor" href="#核心論點" aria-label="Permalink to &quot;核心論點&quot;">​</a></h3><ul><li><strong>「模型沒有變，工作環境變亂了」</strong>：模型性能下降通常是 context debt 而非模型退化</li><li><strong>三層結構</strong>清晰對應 workspace 的 CLAUDE.md/Skills/hooks 分工</li><li><strong>獨立審核 agent 分工</strong>：生成/審核/編輯/事實檢查/人工決策，防止自我讚美循環</li><li><strong>Diff 優先</strong>：審計輸出 Diff 而非直接修改，對齊 APPLY 前 gate 原則</li></ul><h3 id="關鍵數據-工具" tabindex="-1">關鍵數據 / 工具 <a class="header-anchor" href="#關鍵數據-工具" aria-label="Permalink to &quot;關鍵數據 / 工具&quot;">​</a></h3><ul><li>三層結構：長期上下文 / Skills / 審核機制</li><li>七類 context debt 問題清單</li><li>審計 prompt（輸出結構：問題清單 + 風險等級 + 推薦結構 + Diff）</li><li>實際案例：GiftX 項目中使用 Fable 5</li></ul><h3 id="批判性觀察" tabindex="-1">批判性觀察 <a class="header-anchor" href="#批判性觀察" aria-label="Permalink to &quot;批判性觀察&quot;">​</a></h3><ul><li>「AI 工作負債」框架對 workspace 維護協議高度適用</li><li>審計 prompt 的「先不修改，輸出 Diff 讓人審核」直接對應 core.md §APPLY</li><li>獨立審核 agent 分工在中文 AI 創作場景有具體操作路徑</li><li>七類 context debt 問題清單可直接納入 maintenance-protocol.md</li><li>文章較短（3199 字），缺少技術實作細節；基於個人項目經驗，無定量數據</li></ul><hr><h2 id="評分" tabindex="-1">評分 <a class="header-anchor" href="#評分" aria-label="Permalink to &quot;評分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>分數</th><th>說明</th></tr></thead><tbody><tr><td>A. Workspace 可行動性 (30%)</td><td>8/10</td><td>審計 prompt 直接可用；三層結構對應 workspace；七類 debt 問題清單可納入維護協議</td></tr><tr><td>B. 創新性 (20%)</td><td>7/10</td><td>AI 工作負債框架清晰；三層結構分類；Diff 優先審計流程</td></tr><tr><td>C. 證據品質 (20%)</td><td>6/10</td><td>個人 GiftX 案例，無定量數據；機制解釋清楚</td></tr><tr><td>D. 技術深度 (15%)</td><td>7/10</td><td>Skills 觸發機制說明；獨立審核角色拆分；CLAUDE.md vs Auto Memory 區分</td></tr><tr><td>E. 泛化性 (15%)</td><td>7.5/10</td><td>不限 Fable 5，任何長期 AI 系統的維護原則</td></tr><tr><td><strong>加權總分</strong></td><td><strong>7.2/10</strong></td><td>8×0.3+7×0.2+6×0.2+7×0.15+7.5×0.15</td></tr></tbody></table><p><strong>整合決策</strong>：Rule <strong>理由</strong>：七類 context debt 問題清單可加入 maintenance-protocol.md；審計 prompt 和 Diff 優先原則可補充 autoload-evolution；獨立 agent 分工規則（禁止生成者自我審核）可補充 subagent-strategy.md。</p>`,39)])])}const b=a(l,[["render",i]]);export{g as __pageData,b as default};
